-- D&D 3.0 Psionics Handbook feat categories.
WITH desired(slug,category) AS (VALUES
('ph3e-combat-manifestation','psionic'),('ph3e-psionic-dodge','psionic'),('ph3e-improved-psicrystal','psionic'),('ph3e-inertial-armor','psionic'),('ph3e-inner-strength','psionic'),('ph3e-talented','psionic'),('ph3e-body-fuel','psionic'),('ph3e-trigger-power','psionic'),('ph3e-mental-adversary','psionic'),('ph3e-disarm-mind','psionic'),('ph3e-mental-leap','psionic'),('ph3e-metacreative','psionic'),('ph3e-psionic-shot','psionic'),('ph3e-fell-shot','psionic'),('ph3e-return-shot','psionic'),('ph3e-great-sunder','psionic'),('ph3e-psionic-weapon','psionic'),('ph3e-deep-impact','psionic'),('ph3e-power-penetration','psionic'),('ph3e-greater-power-penetration','psionic'),('ph3e-psionic-body','psionic'),('ph3e-psionic-fist','psionic'),('ph3e-power-touch','psionic'),('ph3e-unavoidable-strike','psionic'),('ph3e-psionic-focus','psionic'),('ph3e-greater-psionic-focus','psionic'),('ph3e-psychic-bastion','psionic'),('ph3e-mind-trap','psionic'),('ph3e-psychoanalyst','psionic'),('ph3e-psychic-inquisitor','psionic'),('ph3e-rapid-metabolism','psionic'),('ph3e-psionic-metabolism','psionic'),('ph3e-speed-of-thought','psionic'),('ph3e-psionic-charge','psionic'),('ph3e-up-the-walls','psionic'),('ph3e-stand-still','psionic'),('ph3e-craft-crystal-capacitor','item_creation'),('ph3e-craft-dorje','item_creation'),('ph3e-craft-psionic-arms-and-armor','item_creation'),('ph3e-craft-universal-item','item_creation'),('ph3e-encode-stone','item_creation'),('ph3e-scribe-tattoo','item_creation'),('ph3e-delay-power','metapsionic'),('ph3e-enlarge-power','metapsionic'),('ph3e-extend-power','metapsionic'),('ph3e-persistent-power','metapsionic'),('ph3e-heighten-power','metapsionic'),('ph3e-hide-power','metapsionic'),('ph3e-master-dorje','metapsionic'),('ph3e-maximize-power','metapsionic'),('ph3e-quicken-power','metapsionic'),('ph3e-twin-power','metapsionic'))
INSERT OR IGNORE INTO dnd35_feat_category_assignments(feat_id,category)
SELECT f.id,d.category FROM desired d JOIN dnd35_feats f ON f.slug=d.slug AND f.owner_user_id IS NULL;
